import { useEffect, useMemo, useState } from 'react'
import { BadgeCheck, Building2, Scale } from 'lucide-react'
import { getAnalytics, getCompliance } from '../../api/gcc'
import CategoryBarChart from '../../components/CategoryBarChart'
import CategoryPieChart from '../../components/CategoryPieChart'
import StatCard from '../../components/StatCard'

export default function GccDashboard() {
  const [analytics, setAnalytics] = useState(null); const [compliance, setCompliance] = useState(null)
  useEffect(() => { Promise.all([getAnalytics(), getCompliance()]).then(([a,c])=>{setAnalytics(a);setCompliance(c)}).catch(console.error) }, [])
  const society = analytics?.societies?.[0]; const barData = useMemo(() => society ? [{ label: 'Current', ...society.by_category }] : [], [society])
  return <div className="space-y-7"><div><p className="text-sm text-moss">Greater Chennai Corporation · oversight view</p><h1 className="text-4xl text-forest">Segregation compliance</h1></div><section className="grid gap-6 lg:grid-cols-[.85fr_1.15fr]"><article className="bg-forest p-8 text-paper"><p className="text-sm uppercase tracking-[.15em] text-[#c8d7c8]">Society compliance</p><p className="mt-4 font-display text-7xl">{compliance?.compliance_percent ?? 0}%</p><p className="mt-4 max-w-sm text-sm leading-6 text-[#dce5da]">Items classified with confidence at or above 0.50, used as the current segregation-quality proxy.</p><div className="mt-7 h-3 bg-[#526c58]"><div className="h-3 bg-terracotta" style={{width:`${compliance?.compliance_percent ?? 0}%`}}/></div></article><div className="grid gap-4 sm:grid-cols-3"><StatCard icon={BadgeCheck} label="Verified items" value={compliance?.correctly_segregated ?? 0} tone="moss"/><StatCard icon={Scale} label="Total waste" value={`${Math.round(society?.total_weight_grams || 0)} g`} tone="terracotta"/><StatCard icon={Building2} label="Societies" value={analytics?.societies?.length ?? 0}/></div></section><div className="grid gap-6 xl:grid-cols-2"><section className="panel p-6"><h2 className="section-title">Category distribution</h2><CategoryPieChart data={society?.by_category || {}}/></section><section className="panel p-6"><h2 className="section-title">Aggregate category trend</h2><p className="mt-1 text-sm text-moss">One connected society today; this chart expands as societies are onboarded.</p><div className="mt-5"><CategoryBarChart data={barData}/></div></section></div><section><div className="mb-3 flex items-center justify-between"><h2 className="section-title">Society portfolio</h2><span className="text-sm text-moss">Designed for multi-society rollout</span></div><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{(analytics?.societies || []).map((item)=><article key={item.society_id} className="panel border-t-4 border-terracotta p-5"><p className="text-xs font-bold uppercase tracking-[.12em] text-moss">{item.society_id}</p><h3 className="mt-2 text-2xl text-forest">{item.resident_count} residents</h3><p className="mt-3 text-sm text-moss">{item.event_count} recorded events · {Math.round(item.total_weight_grams)} g processed</p></article>)}</div></section></div>
}
